const N = $('Normalize').first().json;
const M = (N.messages && N.messages[0]) || {};
const isImage = !!M.image && !M.document;
const doc = M.document || M.image || {};
const fname = doc.filename || (isImage ? 'صورة' : 'ملف');
const items = $input.all();
let text = '';
if (items.length && typeof items[0].json.text === 'string') text = items.map(i => i.json.text || '').join('\n');
else if (items.length && !items[0].json.ok && !items[0].json.error && !items[0].json.word_error) text = items.slice(0, 250).map(i => Object.values(i.json).map(v => v == null ? '' : String(v)).join(' | ')).join('\n');
text = String(text || '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').slice(0, 9000);
let arch = 'محفوظ في بريد الشركة';
try { const g = $('Archive File to Gmail').first().json; if (!g || g.error) arch = 'تعذّر حفظه في بريد الشركة: ' + ((g && g.error && (g.error.message || g.error)) || 'سبب غير معروف'); } catch (e) { arch = 'تعذّر حفظه في بريد الشركة.'; }
const cap = String(doc.caption || '').trim();
const kind = isImage ? 'صورة' : 'ملف';
const how = isImage ? 'قُرئت بـ Azure Vision' : (/pdf/i.test(doc.mime_type || fname) ? 'استُخرج نص PDF' : /word|docx/i.test((doc.mime_type || '') + fname) ? 'استُخرج نص Word' : /sheet|excel|xls|csv/i.test((doc.mime_type || '') + fname) ? 'قُرئت صفوف الجدول' : '');
const head = '[' + kind + ' من باهر عبر واتساب] الاسم: ' + fname + ' · النوع: ' + (doc.mime_type || '—') + ' · ' + arch + (how ? ' · ' + how : '') + (cap ? '\nتعليق باهر: ' + cap : '');
let why = 'نوع غير مدعوم بعد.';
if (/pdf/i.test(doc.mime_type || fname)) why = 'الـPDF غالباً ممسوح ضوئياً (صورة بلا نص) — اطلبي من باهر إرسال الصفحات كصور وستُقرأ.';
else if (/msword|\.doc$/i.test((doc.mime_type || '') + ' ' + fname)) why = 'ملف Word قديم (.doc) — اطلبي من باهر حفظه docx أو PDF أو إرساله صوراً.';
else if (isImage) why = 'تعذّرت قراءة الصورة هذه المرة — اطلبي إعادة إرسالها بدقة أعلى.';
const body = text ? ('\n\nالمحتوى المستخرج (قد يكون مبتوراً):\n' + text) : ('\n\nلم يُستخرج نص: ' + why + ' قولي ذلك لباهر صراحة ولا تخمّني المحتوى.');
const rules = '\n\nتعليمات: 1) اقرئي المحتوى ونفّذي ما يقتضيه (مهمة، صفقة، موعد، استشارة) في الجولة نفسها، وإن كتب باهر تعليقاً فهو المطلوب. 2) أي مستند مالي (فاتورة، إيصال تحويل، كشف حساب) → سلّميه لعبدالرحمن عبر Consult Executive Team (abdulrahman-intake) بالمحتوى كاملاً. عقد أو مستند قانوني → abdulaziz-intake. مستند حكومي (سجل، رخصة، إقامة) → mishari-intake. 3) قولي لباهر بسطرين ما فهمتِه من الملف وما فعلتِه به وأين حُفظ. 4) لا تخترعي أرقاماً غير موجودة في النص.';
return [{ json: { ...N, msgType: isImage ? 'image' : 'document', userText: head + body + rules } }];

const it = $input.first();
const b = it.binary && it.binary.data;
if (!b) return [{ json: { text: '', word_error: 'no binary' } }];
return [{ json: it.json, binary: { data: { ...b, fileName: 'document.zip', fileExtension: 'zip', mimeType: 'application/zip' } } }];

const it = $input.first();
const bin = it.binary || {};
const key = Object.keys(bin).find(k => /(^|\/)document\.xml$/.test(String(bin[k].fileName || '')));
if (!key) return [{ json: { text: '', word_error: 'word/document.xml not found' } }];
const buf = await this.helpers.getBinaryDataBuffer(0, key);
let x = buf.toString('utf8');
x = x.replace(/<w:tab\/>/g, '\t').replace(/<w:br[^>]*\/>/g, '\n').replace(/<\/w:p>\s*<\/w:tc>/g, ' | ').replace(/<\/w:tr>/g, '\n').replace(/<\/w:p>/g, '\n').replace(/<[^>]+>/g, '');
x = x.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
return [{ json: { text: x.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, 12000) } }];
